package com.chubb.claims.claim;

import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.PastOrPresent;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * Create request. Deliberately has no id, claimId or claimantId: the claim number is generated by the server and the
 * claimant is whoever the token says they are.
 */
public record CreateClaimRequest(
        @NotBlank @Size(max = 200) String claimantName,
        @NotBlank @Email @Size(max = 254) String claimantEmail,
        @NotBlank @Pattern(regexp = CreateClaimRequest.POLICY_NUMBER, message = CreateClaimRequest.POLICY_NUMBER_MESSAGE) String policyNumber,
        @NotBlank @Pattern(regexp = "[A-Z]{2}", message = "must be a 2-letter upper-case market code, e.g. SG") String market,
        @NotNull ClaimType claimType,
        @NotBlank @Size(max = 2000) String incidentDescription,
        @NotNull @PastOrPresent LocalDate incidentDate,
        @NotNull @Positive @Digits(integer = 17, fraction = 2) BigDecimal claimedAmount,
        @NotBlank @Pattern(regexp = "[A-Z]{3}", message = "must be a 3-letter upper-case ISO currency code, e.g. INR") String currency) {

    /** 3 to 50 characters: letters, digits, '/', '_' or '-', starting with a letter or digit (the format is the insurer's own, so only the characters are checked). */
    public static final String POLICY_NUMBER = "^[A-Za-z0-9][A-Za-z0-9/_-]{2,49}$";
    public static final String POLICY_NUMBER_MESSAGE =
            "must be 3-50 characters: letters, digits, '/', '_' or '-', starting with a letter or digit";
}
